    cld                                      ; 401DA
    rr xor, ax, ax                           ; 401DB
    rr mov, bx, ax                           ; 401DD
    rr mov, cx, ax                           ; 401DF
    rr mov, dx, ax                           ; 401E1
    mov ds,ax                                ; 401E3
    mov es,ax                                ; 401E5
    mov ss,ax                                ; 401E7
