    pusha                                    ; 4F2BF
    mov ax,0x4000                            ; 4F2C0
    mov ds,ax                                ; 4F2C3
    mov si,0xf2fa                            ; 4F2C5
    mov ax,0x1000                            ; 4F2C8
    mov es,ax                                ; 4F2CB
    mov di,0x0                               ; 4F2CD
    mov cx,0x4                               ; 4F2D0
    out 0xc1,al                              ; 4F2D3
    repe cmpsw                               ; 4F2D5
    jz short loc_F2F3                        ; 4F2D7
    mov si,0xf2fa                            ; 4F2D9
    mov di,0x0                               ; 4F2DC
    mov cx,0x4                               ; 4F2DF
    rep movsw                                ; 4F2E2
    mov ax,0x1000                            ; 4F2E4
    mov ds,ax                                ; 4F2E7
    mov di,0x8                               ; 4F2E9
    rr xor, ax, ax                           ; 4F2EC
    mov cx,0xfc                              ; 4F2EE
    rep stosw                                ; 4F2F1
loc_F2F3:
